function synthesisEditor(panel,item,rolls,legacy,getGrade,onChange){
const section=el('section',undefined,'synthesis-editor'),synthHeader=el('div',undefined,'synthesis-header'),heading=el('h3','Synthesis effects'),maxAllBtn=el('button','Max all rolls','synthesis-max-all'),hint=el('p',undefined,'muted'),rows=el('div');maxAllBtn.type='button';synthHeader.append(heading,maxAllBtn);section.append(synthHeader,hint,rows);panel.append(section);
function draw(){const grade=getGrade(),choices=Synthesis.choices(item,grade,rules,effectDB),capacity=Synthesis.capacity(grade,item,rules);section.hidden=!choices.length&&!rolls.length&&!legacy.length;maxAllBtn.hidden=!rolls.length;maxAllBtn.onclick=()=>{for(const roll of rolls){const cur=choices.find(g=>g.id===roll.group);if(cur)roll.value=cur.grades[grade].max;}draw();onChange?.();};hint.textContent=`${rolls.length} / ${capacity} effects · ${grades[grade]} · Database ranges for this item. Choose an actual roll; changing grade does not silently reroll effects.`;rows.replaceChildren();if(legacy.length){const old=el('div',undefined,'effect pending'),clear=el('button','Remove legacy synthesis');old.append(el('p','This saved item has legacy manual synthesis values. Remove them and select database rolls below. They remain preserved until removed.'),clear);clear.onclick=()=>{legacy.splice(0);draw();onChange?.();};rows.append(old);}if(!choices.length)rows.append(el('p','No nonzero synthesis rolls in the database for this item and grade.','muted'));
for(const roll of rolls){const row=el('div',undefined,'synthesis-row'),select=el('select'),input=el('input'),remove=el('button','×'),range=el('small',undefined,'muted'),max=el('button','Max');const current=choices.find(g=>g.id===roll.group);for(const g of choices.filter(g=>g.id===roll.group||!rolls.some(r=>rules.synthesis.groups[r.group]?.unit_attribute_id===g.unit_attribute_id))){const o=el('option',g.name+(g.unit==='%'?' (%)':''));o.value=g.id;select.append(o);}if(!current){const o=el('option','Unavailable at this grade / item');o.value=roll.group;select.append(o);row.classList.add('pending');}select.value=roll.group;select.setAttribute('aria-label','Synthesis effect');const scale=current?.scale||1;input.type='number';input.step=scale;input.value=Number((roll.value*scale).toFixed(5));input.setAttribute('aria-label','Synthesis roll value');if(current){input.min=current.min*scale;input.max=current.max*scale;range.textContent=`${Number((current.min*scale).toFixed(4))} to ${Number((current.max*scale).toFixed(4))}${current.unit}`;}else range.textContent='Remove or change this effect before equipping.';input.oninput=()=>{const value=Number(input.value)/scale;roll.value=Math.abs(value-Math.round(value))<1e-6?Math.round(value):value;onChange?.();};select.onchange=()=>{const next=choices.find(g=>g.id===Number(select.value));roll.group=next.id;roll.value=next.grades[grade].max;draw();onChange?.();};remove.setAttribute('aria-label','Remove synthesis effect');remove.onclick=()=>{rolls.splice(rolls.indexOf(roll),1);draw();onChange?.();};max.disabled=!current;max.onclick=()=>{roll.value=current.grades[grade].max;draw();onChange?.();};row.append(select,input,max,remove,range);rows.append(row);}
for(let index=rolls.length;index<capacity&&choices.length;index++){const row=el('div',undefined,'synthesis-row'),select=el('select'),placeholder=el('option','Select synthesis effect…'),input=el('input'),max=el('button','Max'),remove=el('button','×'),range=el('small','Empty effect slot','muted');placeholder.value='';select.append(placeholder);for(const g of choices.filter(g=>!rolls.some(r=>rules.synthesis.groups[r.group]?.unit_attribute_id===g.unit_attribute_id))){const option=el('option',g.name+(g.unit==='%'?' (%)':''));option.value=g.id;select.append(option);}select.value='';select.setAttribute('aria-label','Synthesis effect');select.disabled=select.options.length===1;input.type='number';input.disabled=true;input.setAttribute('aria-label','Synthesis roll value');max.disabled=true;remove.disabled=true;select.onchange=()=>{const g=choices.find(g=>g.id===Number(select.value));if(g){rolls.push({group:g.id,value:g.grades[grade].max});draw();onChange?.();}};row.append(select,input,max,remove,range);rows.append(row);}}

draw();return draw;}


