function renderEquipmentSets(itemContainer,socketContainer,target,draft){
 const equipment={...state.equipment,[target]:draft};
 const memberships=id=>[...new Set([effectDB.items[id]?.eiset_id,...(rules.enchants[id]||[]).map(row=>row.eiset_id)].filter(Boolean))];
 const itemIds=memberships(draft.id),socketIds=[...new Set([draft.enchant,...draft.gems].filter(Boolean).flatMap(memberships))];
 for(const [container,ids,isSocket]of [[itemContainer,itemIds,false],[socketContainer,socketIds,true]]){
  container.replaceChildren();container.hidden=!ids.length;
  for(const id of ids){const members=[];for(const entry of Object.values(equipment)){const candidates=isSocket?[entry.enchant||entry.lunasigil,...(entry.gems||[])].filter(Boolean):[entry.id];for(const member of candidates)if(memberships(member).includes(id))members.push(member);}
   const count=members.length,levels=members.map(member=>effectDB.items[member]?.level??find('items',member)?.level).filter(Number.isFinite),level=levels.length?Math.min(...levels):null;
   container.append(el('h3',isSocket?'Lunagem / Lunafrost set effects':'Equipment set effects'));
   const memberNames=members.map(member=>find('items',member)?.name).filter(Boolean),prefix=memberNames[0]?.split(' ')||[];while(prefix.length&&memberNames.some(name=>!name.startsWith(prefix.join(' '))))prefix.pop();container.append(el('small',(prefix.join(' ')||'Set #'+id)+' · '+count+' pieces','muted'));
   for(const bonus of effectDB.sets[id]||[]){const active=count>=bonus.num_pieces;const entries=bonus.verified_override?[bonus.verified_override]:EquipmentEffects.setTierModifiers(id,bonus,effectDB).map(mod=>{if(mod.unit_modifier_type_id===1){const meta=effectDB.attributes[mod.unit_attribute_id];return {name:meta?.name||'Unknown effect',value:EquipmentEffects.roundEven(mod.value+mod.linear_level_bonus*(level||0)/100),unit:'% of base'};}return EquipmentEffects.resolve(mod,level,effectDB);}).filter(entry=>!entry.reason);const text=buffTooltipEntries(entries).map(entry=>entry.name+' '+(entry.value>0?'+':'')+Number(entry.value.toFixed(3))+entry.unit).join(' · ')||(bonus.proc_id?'Triggered effect':clean(effectDB.buffs[bonus.buff_id]?.desc||'Special effect'));container.append(el('div','['+Math.min(count,bonus.num_pieces)+'/'+bonus.num_pieces+' pieces] '+text+(active?' · Active':''),active?'set-effect-active':'set-effect-inactive'));}
  }
 }
}

