  for(const passive of passiveRows){const buff=find('buffs',passive.buff_id);if(!buff)continue;const selected=state.passives.includes(passive.id),button=el('button',undefined,'class-skill-icon'+(selected?' selected':''));button.dataset.passiveId=passive.id;button.type='button';button.title=buff.name+' · '+passive.req_points+' prerequisite points';button.setAttribute('aria-label','Passive: '+buff.name);button.setAttribute('aria-pressed',String(selected));button.append(itemIcon(buff,'✦'));button.onclick=()=>toggleClassPoint('passives',passive.id);attachBuffTooltip(button,buff,()=>equipmentSummary().effects,passive);passives.append(button);

  }
  column.append(el('h4','Skills'),skills,el('h4','Passives'),passives);if(abyssal.children.length)column.append(el('h4','Abyssal skills'),abyssal);container.append(column);
