function attackSourceParts(label,change,before,after,db){
 const attr={'Melee Attack':'melee_dps_inc','Ranged Attack':'ranged_dps_inc','Magic Attack':'spell_dps_inc','Healing Power':'heal_dps_inc'}[label];if(!attr||!Number.isFinite(change))return null;const attributes=[attr,...(attr==='heal_dps_inc'?['heal_dps']:attr==='spell_dps_inc'?['spell_dps']:[])];const bonus=summary=>summary.effects.pending.filter(e=>e.raw?.unit_modifier_type_id===1&&attributes.includes(db.attributes[e.raw.unit_attribute_id]?.attribute)).reduce((total,e)=>total+EquipmentEffects.roundEven(e.raw.value+e.raw.linear_level_bonus*(e.level??55)/100),0);const percent=bonus(before);if(!percent||Math.abs(percent-bonus(after))>1e-8||1+percent/100===0)return null;const base=change/(1+percent/100),modifiers=change-base;return Math.abs(modifiers)>=.005?{base,modifiers}:null;
}

function buffTooltipEntries(entries){
 let rows=[...entries];const equal=group=>group.length&&group.every(entry=>entry.value===group[0].value&&entry.unit===group[0].unit&&(entry.raw?.unit_modifier_type_id??0)===(group[0].raw?.unit_modifier_type_id??0));
 function combine(attributes,name,optional=[]){const group=rows.filter(entry=>attributes.includes(entry.attribute));if(!attributes.every(attribute=>group.some(entry=>entry.attribute===attribute))||group.length!==attributes.length||!equal(group))return false;const extra=rows.filter(entry=>optional.includes(entry.attribute)&&equal([group[0],entry]));const remove=new Set([...group,...extra]);rows=rows.filter(entry=>!remove.has(entry));rows.push({...group[0],name,attribute:'display_group',raw:undefined});return true;}
 const expected=[...Array.from({length:20},(_,index)=>99+index),138,195],professions=rows.filter(entry=>expected.includes(entry.raw?.unit_attribute_id));
 if(expected.every(id=>professions.some(entry=>entry.raw.unit_attribute_id===id))&&professions.length===expected.length&&equal(professions)){rows=rows.filter(entry=>!professions.includes(entry));rows.push({...professions[0],name:'All proficiencies',attribute:'display_group',raw:undefined});}
 combine(['incoming_melee_damage_add','incoming_ranged_damage_add','incoming_spell_damage_add'],'Fixed Damage Reduction',['incoming_siege_damage_add']);
 combine(['incoming_melee_damage_mul','incoming_ranged_damage_mul','incoming_spell_damage_mul'],'Received Damage',['incoming_siege_damage_mul']);
 combine(['melee_damage_mul','ranged_damage_mul','spell_damage_mul'],'Skill Damage');
 combine(['melee_dps_inc','ranged_dps_inc'],'Attack',['mainhand_dps','offhand_dps','ranged_dps']);
 combine(['spell_dps_inc','heal_dps_inc'],'Magic Attack & Healing Power');
 combine(['spell_dps','heal_dps'],'Magic Attack & Healing Power');
 combine(['melee_anti_miss_mul','ranged_anti_miss_mul','spell_anti_miss_mul'],'Accuracy');
 combine(['backattack_melee_damage_mul','backattack_ranged_damage_mul','backattack_spell_damage_mul'],'Backstab Damage');
 combine(['melee_critical_mul','ranged_critical_mul','spell_critical_mul'],'Critical Rate');
 combine(['melee_critical_bonus','ranged_critical_bonus','spell_critical_bonus'],'Critical Damage');
 combine(['armor','magic_resist'],'Physical & Magic Defense');
 const speedAttributes=['melee_speed_mul','ranged_speed_mul','global_cooldown_mul','attack_anim_speed_mul','attack_speed_mul'],speeds=rows.filter(entry=>speedAttributes.includes(entry.attribute));
 if(speeds.length){rows=rows.filter(entry=>!speedAttributes.includes(entry.attribute));const seen=new Set();for(const speed of speeds){const key=JSON.stringify([speed.value,speed.unit,speed.raw?.unit_modifier_type_id??0]);if(seen.has(key))continue;seen.add(key);rows.push({...speed,name:'Attack Speed',attribute:'display_group',value:speed.unit==='%'?Number((speed.value*10).toFixed(6)):speed.value,unit:speed.unit==='%'?'':speed.unit,raw:undefined});}}
 const priority=['Attack & Healing Power','Attack','Melee Attack','Ranged Attack','Magic Attack & Healing Power','Magic Attack','Healing Power','Fixed Damage Reduction','Received Damage','Received Melee Damage','Received Ranged Damage','Received Magic Damage','Attack Speed','Cast Time','Skill Damage'];
 const rank=entry=>{const index=priority.indexOf(entry.name);return index>=0?index:100;};return rows.sort((a,b)=>rank(a)-rank(b));
}

function buffTooltipNotes(description){
 // Descriptions can contain unscaled placeholders or raw numbers. Only add
 // production time and stacking restrictions; numeric combat stats use resolved entries.
 return clean(description||'').split(/\r?\n/).map(line=>line.trim()).filter(line=>line&&!line.includes('#{')&&(/^(?:Production|Crafting) Time\b/i.test(line)||/does not stack|cannot stack|can.t stack|not stackable/i.test(line)));
}

