function toggleClassPoint(kind,id){try{const before=state.passives||[],next=ClassPoints.toggle(state,kind,id,DB.skills,effectDB.passives,rules.class_skills);const removed=before.filter(value=>!next.passives.includes(value)),related=new Set(removed.flatMap(value=>[...(effectDB.passives[value]?.children||[]).map(child=>child.buff_id),...(effectDB.passives[value]?.related||[])]));next.buffs=next.buffs.filter(value=>!related.has(value));next.conditions=[];state=next;refreshClassSelectionPanels();if(removed.length>(kind==='passives'?1:0))toast('Dependent passives were removed because their point requirements are no longer met.');}catch(error){toast(error.message);}}
function syncClassPointControls(){
 const used=ClassPoints.total(state,rules.class_skills),abyssalCount=state.skills.filter(id=>ClassPoints.isAbyssal(id,rules.class_skills)).length,clsTitle=ClassPoints.className(state.classes);$('classEditorSummary').textContent=(clsTitle?clsTitle+' · ':'')+used+' / 28 points · '+(28-used)+' available · '+(state.skills.length-abyssalCount)+' skills · '+state.passives.length+' passives'+(abyssalCount?' · '+abyssalCount+' Abyssal (separate)':'');
 for(const column of $('classEditorColumns').children){const ability=column.dataset.ability;if(!ability)continue;const points=ClassPoints.spent(state,ability,DB.skills,effectDB.passives,rules.class_skills);column.querySelector('.class-tree-points').textContent=points+' points in '+names[ability];
  for(const button of column.querySelectorAll('.class-skill-icon')){const isPassive=!!button.dataset.passiveId,id=Number(button.dataset.passiveId||button.dataset.skillId),chosen=state[isPassive?'passives':'skills'].includes(id),required=isPassive?effectDB.passives[id].req_points:0,abyssal=!isPassive&&ClassPoints.isAbyssal(id,rules.class_skills),locked=!chosen&&!abyssal&&(used>=28||points<required);button.classList.toggle('selected',chosen);button.classList.toggle('points-locked',locked);button.classList.toggle('passive-locked',isPassive&&locked);if(isPassive)button.dataset.requiredPoints=required;button.setAttribute('aria-pressed',String(chosen));button.setAttribute('aria-disabled',String(locked));const name=isPassive?find('buffs',effectDB.passives[id].buff_id)?.name:find('skills',id)?.name;button.title=name+(isPassive?' · Requires '+required+' points in '+names[ability]:'')+(locked?(used>=28?' · All 28 points allocated':' · Locked'):'');}
 }
}

function buffTooltipEffectData(buff,audit){
 const source='Buff #'+buff.id,entries=audit.entries.filter(entry=>entry.buff_id===buff.id),pending=audit.pending.filter(entry=>entry.source===source||entry.source?.startsWith(source+' · '));
 if(entries.length||pending.length)return {entries,pending,applied:true};
 const result={entries:[],pending:[],applied:false},record=effectDB.buffs[buff.id];
 for(const modifier of record?.modifiers||[]){const entry={...EquipmentEffects.resolve(modifier,state.level||55,effectDB),level:state.level||55};(entry.reason?result.pending:result.entries).push(entry);}
 return result;
}

function recordDescriptionLines(description){return clean(description||'No description available.').replace(/--(?=\d)/g,'-').replace(/\+\+(?=\d)/g,'+').split(/\r?\n/).map(line=>line.trim()).filter(Boolean);}

function appendItemSpecialEffects(container,id){const record=effectDB.item_special_effects?.[id];if(!record)return;for(const [key,title]of [['combo','Combo Effect'],['use','Use Effect']]){const description=record[key];if(!description)continue;container.append(el('h4',title));for(const line of recordDescriptionLines(description))container.append(el('div',line,'tooltip-effect special-effect-description'));}}

